{
  "identity": {
    "name": "IT Secure LLC",
    "location": "148 E Cordoba Ct, Meridian, ID 83646, United States",
    "claims": [
      {
        "statement": "The legal name of the business is IT Secure LLC, doing business as IT Secure.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/privacy-policy/",
        "quote": "This privacy notice for IT Secure LLC (doing business as IT Secure) (\"we,\" \"us,\" or \"our\"), describes how and why we might collect"
      },
      {
        "statement": "The company is based in Meridian, Idaho, and serves Boise, Nampa, Eagle, the Treasure Valley of Idaho, and the Willamette Valley of Oregon.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/",
        "quote": "Based in Meridian, we provide fast, reliable IT support to businesses throughout Boise, Nampa, Eagle, and the Treasure Valley."
      },
      {
        "statement": "The company publishes a postal address of 148 E Cordoba Ct, Meridian, ID 83646, United States in its privacy policy.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/privacy-policy/",
        "quote": "IT Secure LLC Data Protection Officer 148 E Cordoba Ct Meridian, ID 83646 United States"
      }
    ]
  },
  "industry": {
    "industry": "Information Technology and Managed Services (Managed Service Provider / MSP)",
    "activities": [
      "Managed IT Support and Co-Managed IT Support",
      "Cybersecurity Services and Compliance Management",
      "Business Network and Wi-Fi Management",
      "Data Backup and Disaster Recovery",
      "Cloud Managed Services",
      "Business Data Analysis",
      "Communications VoIP and Unified Communications Services",
      "Artificial Intelligence (AI) Solutions and Digital Transformation Consulting"
    ],
    "claims": [
      {
        "statement": "IT Secure operates as a Managed Service Provider delivering outsourced IT services to businesses.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/partnerships/",
        "quote": "Partnerships with leading technology companies are integral to the success of a Managed Service Provider (MSP) that deliver outsourced IT services to businesses."
      },
      {
        "statement": "The company provides managed IT support, cybersecurity, and support for Apple and Microsoft environments.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/",
        "quote": "We offer proactive managed IT support, industry-leading cybersecurity, and expert assistance for both Apple and Microsoft environments—covering all your business technology needs"
      },
      {
        "statement": "The company offers AI solutions to automate business processes, enhance decision-making, and provide predictive analytics.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/services/",
        "quote": "Deploying AI-based tools and algorithms to automate processes, enhance decision-making, and provide predictive analytics across various business operations."
      },
      {
        "statement": "IT Secure LLC is a B2B technology and IT services provider rather than a residential or home-service trade contractor.",
        "label": "inference",
        "sourceUrl": "https://itsecure.tech/services/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://itsecure.tech/",
    "claims": [
      {
        "statement": "The company's official website is https://itsecure.tech/.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/",
        "quote": "IT Secure | Treasure Valley's Trusted Managed Service Provider"
      },
      {
        "statement": "The company states that its team has over 40 years of combined experience in technology and support.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/about/",
        "quote": "With over 40 years of experience in technology and support, we are here to assist you."
      },
      {
        "statement": "The company states it is a Microsoft Partner and an Apple Technical Partner, and integrates with the Google ecosystem.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/partnerships/",
        "quote": "As an Apple Technical Partner, we are able to provide a more complete solution integrated with Apple's seamless experience."
      },
      {
        "statement": "The website links to a client support portal at https://support.itsecure.tech/.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/",
        "quote": "Client Dashboard"
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The company identifies itself as a Limited Liability Company (IT Secure LLC).",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/",
        "quote": "© 2026 IT Secure LLC | All Rights Reserved."
      },
      {
        "statement": "The company states it offers certified support for Apple and Microsoft environments.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/",
        "quote": "Certified Support for MAC & PC"
      }
    ],
    "limitations": "No state contractor license numbers, business registration numbers, or regulatory license identifiers are published on the pages read. Because the business is an IT managed service provider rather than a trade contractor, trade licensing (such as HVAC, plumbing, or electrical) does not apply."
  },
  "existingSoftware": [
    {
      "product": "WePay",
      "purpose": "Payment processing and payment data storage",
      "evidence": {
        "statement": "The company's privacy policy states that payment data is handled and stored by WePay.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/privacy-policy/",
        "quote": "All payment data is handled and stored by WePay."
      }
    },
    {
      "product": "Remote Monitoring and Management (RMM) & Mobile Device Management (MDM) Systems",
      "purpose": "Remote monitoring, patch management, and mobile device management for client IT environments",
      "evidence": {
        "statement": "The company states it uses RMM and MDM systems to monitor and manage client devices and IT tasks remotely.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/services/",
        "quote": "RMM systems remotely monitor client systems, manage IT tasks, and resolve issues, often without needing to physically visit the client site."
      }
    },
    {
      "product": "Automated SMS/MMS Platform",
      "purpose": "Automated and high-volume business SMS/MMS messaging via application, third-party integrations, and APIs",
      "evidence": {
        "statement": "The privacy policy states that automated SMS messaging is available through its platform using tools, third-party integrations, and APIs.",
        "label": "fact",
        "sourceUrl": "https://itsecure.tech/privacy-policy/",
        "quote": "Automated SMS messaging is available through our platform using provided tools, third-party integrations, and APIs."
      }
    },
    {
      "product": "WordPress with Divi Theme and Forminator Plugin",
      "purpose": "Website content management, visual page building, and web contact form handling",
      "evidence": {
        "statement": "The website likely runs on WordPress using the Divi theme and Forminator plugin for its contact form.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    },
    {
      "product": "Calendly",
      "purpose": "Online consultation scheduling widget",
      "evidence": {
        "statement": "The meeting scheduling page likely uses Calendly to book free consultations.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The navigation menu and footer link to a pricing page (https://itsecure.tech/pricing/) that returns an HTTP 404 not-found error.",
      "label": "inference",
      "sourceUrl": "https://itsecure.tech/",
      "quote": null
    },
    {
      "statement": "The company emphasizes live human phone answering over automated bots, stating callers reach a real person every time with no scripts or robots.",
      "label": "fact",
      "sourceUrl": "https://itsecure.tech/",
      "quote": "Reach a real person every time you call—no scripts, no robots, just helpful IT professionals."
    }
  ],
  "problems": [
    {
      "problem": "Broken navigation link to the Pricing page (HTTP 404) on the public website.",
      "label": "inference",
      "basis": "Links to https://itsecure.tech/pricing/ appear in the site navigation and footer on https://itsecure.tech/ and other pages, but fetching https://itsecure.tech/pricing/ returns HTTP 404 not-found."
    },
    {
      "problem": "No confirmed operational or automation problems relevant to ForgeX's service catalog.",
      "label": "inference",
      "basis": "IT Secure LLC is itself a Managed Service Provider offering IT automation, AI solutions, business data analysis, and automated messaging platforms to other businesses, as stated on https://itsecure.tech/services/ and https://itsecure.tech/privacy-policy/."
    }
  ],
  "existingSolutions": [
    {
      "solution": "In-house Managed IT, AI Solutions, Business Data Analysis, Help Desk, and Automated SMS Platforms",
      "addresses": "Process automation, data analytics, customer support triage, and automated lead/client messaging",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended because IT Secure LLC is outside ForgeX's target segment of home-service contractors and already provides IT management, data analytics, and AI automation services in-house."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended. Furthermore, IT Secure LLC explicitly positions its brand against automated phone/support bots ('no scripts, no robots') while offering its own AI and automation services to clients."
  },
  "humanReview": [],
  "risks": [
    {
      "type": "operational",
      "description": "Pitching basic automation services to a Managed Service Provider that already sells AI solutions, cloud management, and business data analysis would be misaligned with ForgeX's home-service contractor focus."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": [
      "The website publishes no service prices (the /pricing/ link returns HTTP 404), and the business is not a fit for ForgeX services."
    ]
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner / Managing Member",
      "Chief Executive Officer / President",
      "Data Protection Officer"
    ],
    "people": [],
    "channels": [
      {
        "kind": "phone",
        "value": "[redacted]",
        "sourceUrl": "https://itsecure.tech/contact/"
      }
    ]
  },
  "discovery": {
    "questions": [],
    "outreachSubject": "",
    "outreachBody": ""
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://itsecure.tech/",
        "usedFor": "Business identity, Meridian location, service areas, core MSP offerings, client dashboard link, and positioning statements."
      },
      {
        "url": "https://itsecure.tech/about/",
        "usedFor": "Company background, remote support and systems management focus, and statement of over 40 years of experience."
      },
      {
        "url": "https://itsecure.tech/services/",
        "usedFor": "Detailed list of primary and support services, including RMM, MDM, Business Data Analysis, Help Desk Support, and Artificial Intelligence (AI) Solutions."
      },
      {
        "url": "https://itsecure.tech/contact/",
        "usedFor": "Business phone number, text support number, and web contact form verification."
      },
      {
        "url": "https://itsecure.tech/partnerships/",
        "usedFor": "MSP industry classification and partnerships with Microsoft, Apple, and Google."
      },
      {
        "url": "https://itsecure.tech/schedule-a-meeting/",
        "usedFor": "Consultation booking page and scheduling script references."
      },
      {
        "url": "https://itsecure.tech/privacy-policy/",
        "usedFor": "Legal entity name (IT Secure LLC), Meridian street address, WePay payment processing usage, and automated SMS/MMS platform capabilities."
      }
    ],
    "limitations": [
      "The /pricing/ page linked across the site returns an HTTP 404 error, so no service pricing is publicly available.",
      "The website does not list employee headcount or name any owners, executives, or managers outside of a customer testimonial (which is excluded under ForgeX evidence rules).",
      "Email addresses on the website are obfuscated behind Cloudflare email protection links."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "IT Secure LLC is a B2B Managed Service Provider (MSP) offering IT support, cybersecurity, cloud services, business data analysis, and AI automation solutions. It falls outside ForgeX's target segment of owner-led home-service contractors (HVAC, plumbing, and electrical) and already owns and sells technology and automation solutions."
  }
}
